// A dependency's `x!` checks nothing: the value keeps flowing as undefined
// through the bindings, parameters and returns it reaches.
function pathOf(m: number): string | undefined {
  return m > 0 ? "p" : undefined;
}
function reg(name: string, path: string): string {
  return name + " " + (path === undefined ? "undef" : path);
}
function widthOf(m: number): number | undefined {
  return m > 0 ? 3 : undefined;
}
function pad(width: number): string {
  return width === undefined ? "none" : String(width);
}
function pass(path: string): string {
  return reg("pass", path);
}
export function resolveAll(modes: number[]): string[] {
  const out: string[] = [];
  for (const m of modes) {
    const p = pathOf(m)!;
    out.push(reg("m" + m, p));
    out.push(pass(p));
    const w = widthOf(m)!;
    out.push(pad(w));
    out.push(pad(widthOf(m)!));
  }
  return out;
}

export interface RoutePathMetadata {
  ctrlPath: string;
  modulePath: string;
  globalPrefix: string;
}
class Factory {
  create(metadata: RoutePathMetadata): string[] {
    const { ctrlPath, modulePath, globalPrefix } = metadata;
    return [globalPrefix + "|" + (modulePath === undefined ? "undef" : modulePath) + "|" + ctrlPath];
  }
}
export class Resolver {
  private readonly factory = new Factory();
  private readonly paths = new Map<number, string>([[1, "mod"]]);
  private pathMetadata(key: number): string | undefined {
    const direct = this.paths.get(key + 10);
    return direct ?? this.paths.get(key);
  }
  private hostOf(key: number): string | string[] | undefined {
    return key === 1 ? "h" : key === 2 ? undefined : ["x", "y"];
  }
  private explore(out: string[], host: string | string[]): void {
    out.push("host " + (host === undefined ? "undef" : Array.isArray(host) ? host.join("+") : host));
  }
  resolve(keys: number[]): string[] {
    const out: string[] = [];
    keys.forEach((key) => {
      const modulePath = this.pathMetadata(key)!;
      const host = this.hostOf(key);
      this.register(out, "g", modulePath);
      this.explore(out, host!);
    });
    return out;
  }
  register(out: string[], globalPrefix: string, modulePath: string): void {
    ["a", "b"].forEach((path) => {
      for (const line of this.factory.create({ ctrlPath: path, modulePath, globalPrefix })) out.push(line);
      const metadata: RoutePathMetadata = { ctrlPath: path, modulePath, globalPrefix };
      out.push(metadata.modulePath === undefined ? "meta undef" : "meta " + metadata.modulePath);
    });
  }
}

export function argumentsLength<T>(keys: string[], metadata: T): number {
  return keys.length ? Math.max(...keys.map((key) => metadata[key].index)) + 1 : 0;
}

interface ParamMetadata {
  index: number;
  data: string;
  factory?: (value: string) => string;
}
export function exchange(keys: string[], rows: object): string[] {
  const metadata = rows as Record<number, ParamMetadata>;
  return keys.map((key) => {
    const { index, data } = metadata[key];
    if (key.includes("custom")) {
      const { factory } = metadata[key];
      return factory === undefined ? "nofactory" : factory(data);
    }
    return key + index + data;
  });
}

interface Extractor {
  key: string;
  extract: (req: { n: number }, res: string) => string;
}
export function extractors(keys: string[], base: number): Extractor[] {
  return keys.map((key, index) => {
    const extract = <TRequest, TResponse>(req: TRequest, res: TResponse) =>
      key + (base + index) + JSON.stringify(req) + String(res);
    return { key, extract };
  });
}


const stored = new Map<string, any>([["r:a", { url: "/a" }], ["n:n", 7], ["s:s", "text"]]);
const registry = { get: (key: string): any => stored.get(key) };
interface Redirect {
  url: string;
}
function redirectOf(key: string): Redirect {
  return registry.get("r:" + key);
}
function countOf(key: string): number {
  return registry.get("n:" + key);
}
function textOf(key: string): string {
  return registry.get("s:" + key);
}
export function reflect(keys: string[]): string[] {
  return keys.map((key) => {
    const redirect = redirectOf(key);
    const count = countOf(key);
    const text = textOf(key);
    return [redirect === undefined ? "none" : redirect.url, count === undefined ? "none" : count, text === undefined ? "none" : text].join("/");
  });
}

class Target {}
class Wrapper {
  constructor(
    readonly inject: unknown,
    readonly metatype: Function | null,
  ) {}
  isNewable(): boolean {
    return this.inject == null && this.metatype && this.metatype.prototype;
  }
}
export function newables(): string[] {
  const wrappers = [new Wrapper(undefined, Target), new Wrapper(1, Target), new Wrapper(undefined, null)];
  return wrappers.map((wrapper) => (wrapper.isNewable() ? "new" : "not"));
}

abstract class Creator {
  abstract make(items: number[]): number[];
  getGlobal?<T extends number[]>(id?: number): T;
  run(): number {
    const g = this.getGlobal && this.getGlobal<number[]>(1);
    return (g ? g.length : 0) + this.make([1, 2]).length;
  }
}
class WithGlobal extends Creator {
  make(items: number[]): number[] {
    return items;
  }
  getGlobal<T extends number[]>(id?: number): T {
    return [id!, id!, id!] as T;
  }
}
class WithoutGlobal extends Creator {
  make(items: number[]): number[] {
    return items;
  }
}
export function creators(): number[] {
  return [new WithGlobal().run(), new WithoutGlobal().run()];
}

class Context {
  private readonly prefix = "ctx:";
  create(callback: (value: string) => string): (value: string) => string {
    const handler =
      <TRequest>(value: string, req: TRequest, next?: string, files: string[] = []) =>
      async () => {
        const result = callback(value);
        return this.prefix + result + JSON.stringify(req) + (next ?? "-") + files.length;
      };
    return (value: string) => {
      void handler(value, { a: 1 });
      return handler(value, { a: 1 }, "n", ["f"]) === undefined ? "none" : "made";
    };
  }
}
export function contexts(): string {
  return new Context().create((value) => value.toUpperCase())("x");
}

enum Method {
  GET = 0,
  POST,
  ALL = 4,
}
export function methodNames(values: number[]): string[] {
  return values.map((value) => Method[value] as keyof typeof Method);
}
function nameOf(method: Method): string {
  return Method[method];
}
export function methodName(value: number): string {
  return nameOf(value === 1 ? Method.POST : Method.ALL);
}

export const describeMethod = (path: string, method: string | number) => `{${path}, ${Method[method]}}`;

interface Logger {
  log(message: string): void;
}
function describeLogger(logger: Logger | string[] | false | undefined): string {
  if ((logger as boolean) !== true && logger != null) {
    return Array.isArray(logger) ? "levels:" + logger.join("+") : "custom";
  }
  return "default";
}
export function loggers(): string[] {
  const custom: Logger = { log() {} };
  return [describeLogger(["error"]), describeLogger(custom), describeLogger(false), describeLogger(undefined)];
}

class Named extends Error {
  constructor() {
    super("x");
    this.name = this.constructor.name;
  }
  label(): string {
    return this.constructor.name.match(/[A-Z][a-z]+|[0-9]+/g)?.join(" ") ?? "Error";
  }
}
class NotFoundThing extends Named {}
function* each(count: number): Generator<number> {
  for (let i = 0; i < count; i++) yield i;
}
async function settle(parts: Iterable<number>, log: string[]): Promise<void> {
  await Promise.all(Array.from(parts).map(async (part) => { log.push("part" + part); }));
}
function pipes(count: number): Promise<void[]> | undefined {
  let pending: Promise<void>[] | undefined;
  for (let i = 0; i < count; i++) (pending ??= []).push(Promise.resolve());
  return pending && Promise.all(pending);
}
export async function names(): Promise<string[]> {
  const log: string[] = [new NotFoundThing().name, new NotFoundThing().label()];
  await settle(each(3), log);
  const none = await pipes(0);
  const some = await pipes(2);
  log.push(none === undefined ? "none" : "some", String(some === undefined ? -1 : some.length));
  return log;
}

function pipeFn(count: number) {
  return <TRequest>(req: TRequest) => {
    let pending: Promise<void>[] | undefined;
    for (let i = 0; i < count; i++) (pending ??= []).push(Promise.resolve());
    return pending && Promise.all(pending);
  };
}
export async function pipeLengths(): Promise<string> {
  const none = await pipeFn(0)("r");
  const some = pipeFn(2)("r");
  return (none === undefined ? "none" : "some") + (some === undefined ? "none" : "pending");
}
